// `curl ipterm.net/me`: a terminal card for the caller's own address, with a Braille world map.
//
// Everything on it comes from Cloudflare's request.cf (via edgeInfo() in worker.js): no outside call,
// no reverse DNS, no rate limit. The worker passes every string through plain() before it gets here,
// so nothing from upstream can carry an escape sequence; the only escape sequences in the card are
// the colors added below.
//
// The map is the 1-degree land grid in landmask.js (generated by tools/build_landmask.mjs from
// public/land.js), drawn with Braille characters: each character is 2 dots wide and 4 tall, and
// terminal cells are about twice as tall as wide, so the dots come out square and the map is a plain
// longitude/latitude grid. It shows 84°N to about 56°S (Antarctica is left out).
import { LAND_MASK } from './landmask.js';

export const ME_WIDTH = { min: 32, max: 120, def: 64 };   // the card's width in columns, frame included

const MAP_TOP = 84, MAP_BOTTOM = -56;
const MASK = Uint8Array.from(atob(LAND_MASK.bits), c => c.charCodeAt(0));
const isLand = (lon, lat) => {
  const col = Math.floor(lon + 180), row = Math.floor(90 - lat);
  if (col < 0 || col >= LAND_MASK.w || row < 0 || row >= LAND_MASK.h) return false;
  const i = row * LAND_MASK.w + col;
  return (MASK[i >> 3] & (0x80 >> (i & 7))) !== 0;
};
// Braille dot bits by position in the 2x4 cell: [column][row].
const DOT = [[0x01, 0x02, 0x04, 0x40], [0x08, 0x10, 0x20, 0x80]];

// The map as rows of { ch, mark }: `cols` characters wide, as tall as the latitude range needs. A dot
// is lit when about a third of the grid cells under it are land, so small islands drop out at narrow
// widths instead of smearing.
function brailleMap(cols, lat, lon) {
  const dotsW = cols * 2, deg = 360 / dotsW;
  const rows = Math.ceil((MAP_TOP - MAP_BOTTOM) / deg / 4);
  const n = Math.max(1, Math.ceil(deg));               // samples per dot side, about one per grid cell
  const lit = (dx, dy) => {
    let landN = 0;
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
      const la = MAP_TOP - (dy + (j + 0.5) / n) * deg;    // the last row can reach past MAP_BOTTOM: kept empty
      if (la > MAP_BOTTOM && isLand(-180 + (dx + (i + 0.5) / n) * deg, la)) landN++;
    }
    return landN * 3 >= n * n;
  };
  let mx = -1, my = -1;
  if (lat != null && lon != null) {
    mx = Math.min(dotsW - 1, Math.max(0, Math.floor((lon + 180) / deg))) >> 1;
    my = Math.min(rows * 4 - 1, Math.max(0, Math.floor((MAP_TOP - lat) / deg))) >> 2;
  }
  const out = [];
  for (let r = 0; r < rows; r++) {
    const line = [];
    for (let c = 0; c < cols; c++) {
      let b = 0;
      for (let x = 0; x < 2; x++) for (let y = 0; y < 4; y++) if (lit(c * 2 + x, r * 4 + y)) b |= DOT[x][y];
      line.push(c === mx && r === my ? { ch: '⣿', mark: true } : { ch: b ? String.fromCharCode(0x2800 + b) : ' ' });
    }
    out.push(line);
  }
  return out;
}

const len = s => Array.from(s).length;
const cut = (s, n) => (len(s) <= n ? s : Array.from(s).slice(0, Math.max(0, n - 1)).join('') + '…');

// Word-wraps a value to `w` columns, at most `max` lines (the last one cut with …). Words longer than a
// line (an IPv6 address on a narrow card) are broken where they must be.
function wrap(s, w, max = 4) {
  const lines = [];
  let cur = '';
  for (let word of s.split(' ')) {
    while (len(word) > w) {
      if (cur) { lines.push(cur); cur = ''; }
      lines.push(Array.from(word).slice(0, w).join(''));
      word = Array.from(word).slice(w).join('');
    }
    if (!cur) cur = word;
    else if (len(cur) + 1 + len(word) <= w) cur += ' ' + word;
    else { lines.push(cur); cur = word; }
  }
  if (cur || !lines.length) lines.push(cur);
  if (lines.length > max) { lines.length = max; lines[max - 1] = cut(lines[max - 1] + ' …', w); }
  return lines;
}

// "10:42 (UTC-4)" in the time zone, or null for a name the runtime doesn't know.
function localTime(tz, now) {
  try {
    const parts = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: '2-digit', minute: '2-digit', hourCycle: 'h23', timeZoneName: 'shortOffset' })
      .formatToParts(now);
    const get = t => (parts.find(p => p.type === t) || {}).value || '';
    return `${get('hour')}:${get('minute')} (${get('timeZoneName').replace(/^GMT/, 'UTC').replace(/^UTC$/, 'UTC+0')})`;
  } catch { return null; }
}

// d: edgeInfo() with every string passed through plain(). opts: width (columns), color (ANSI), redact
// (hide the address), host (for the title and footer), now (for the local time).
export function meCard(d, { width = ME_WIDTH.def, color = false, redact = false, host = 'ipterm.net', now = new Date() } = {}) {
  const W = Math.min(ME_WIDTH.max, Math.max(ME_WIDTH.min, width)), inner = W - 4;
  const paint = (code, s) => (color && s ? `\x1b[${code}m${s}\x1b[0m` : s);
  const C = { frame: '90', title: '1;32', land: '32', mark: '1;93', key: '32', ip: '1', dim: '2' };
  const out = [];
  const row = (plainText, painted = plainText) => out.push(paint(C.frame, '│ ') + painted + ' '.repeat(Math.max(0, inner - len(plainText))) + paint(C.frame, ' │'));
  const rule = (left, right, label) => {
    const l = label ? cut(label, W - 6) : '';
    const body = l ? `─ ${l} ` : '';
    out.push(paint(C.frame, left + body.slice(0, 2)) + paint(C.title, l) + paint(C.frame, (l ? ' ' : '') + '─'.repeat(Math.max(0, W - 2 - len(body))) + right));
  };

  rule('╭', '╮', `${host}/me`);
  row('');
  for (const line of brailleMap(inner, d.lat, d.lon)) {
    const raw = line.map(x => x.ch).join('');
    const painted = color ? line.map(x => paint(x.mark ? C.mark : C.land, x.ch)).join('').replace(/\x1b\[0m\x1b\[32m/g, '') : (line.some(x => x.mark) ? line.map(x => (x.mark ? '@' : x.ch)).join('') : raw);
    row(raw, painted);
  }
  const located = d.lat != null && d.lon != null;
  const caption = located ? `${color ? '⣿' : '@'} about here (your provider's hub, not your home)` : 'location unknown';
  wrap(caption, inner).forEach((l, i) => row(l, i === 0 && located ? paint(C.mark, l[0]) + paint(C.dim, l.slice(1)) : paint(C.dim, l)));
  row('');

  const KEY = 11, vw = inner - KEY;
  const ctry = d.country ? d.country + (d.countryCode ? ` [${d.countryCode}]` : '') : d.countryCode;
  const hidden = d.version === 6 ? 'xxxx:xxxx:xxxx::' : 'xxx.xxx.xxx.xxx';
  const ip = d.ip ? (redact ? hidden : d.ip) : 'unknown';
  const t = d.timezone ? localTime(d.timezone, now) : null;
  const rows = [
    ['ip', ip + (d.version ? `  IPv${d.version}` : ''), C.ip],
    ['network', [d.asn, d.org].filter(Boolean).join('  ')],
    ['location', [d.city, d.region, ctry].filter(Boolean).join(', ')],
    ['time zone', d.timezone ? d.timezone + (t ? `  ${t}` : '') : null],
    ['edge', d.colo ? `${d.colo} (Cloudflare data center)` : null],
  ];
  for (const [k, v, code] of rows) {
    if (!v) continue;
    wrap(v, vw).forEach((l, i) => {
      const key = (i ? '' : k).padEnd(KEY);
      // Only the address itself is bold, not the IPv4/IPv6 tag after it.
      const val = code && i === 0 && l.startsWith(ip) ? paint(code, ip) + l.slice(ip.length) : l;
      row(key + l, paint(C.key, key) + val);
    });
  }
  row('');
  const foot = [`no cookies · no tracking · ${host}/help`, `${host}/help`].find(s => len(s) <= W - 6) || '';
  rule('╰', '╯', foot);
  return out.join('\n') + '\n';
}
